class Guillotine {
    constructor(width, height) {
        this.root = { x: 0, y: 0, w: width, h: height, used: false };
        this.items = [];
        this.totalArea = width * height;
    }

    insert(item) {
        const nodes = [
            { node: this.findNode(this.root, item.x, item.y), rotated: false }
        ].filter(({ node }) => node !== null);

        if (nodes.length === 0) {
            return null;
        }

        nodes.sort((a, b) => (a.node.w * a.node.h) - (b.node.w * b.node.h));
        const { node, rotated } = nodes[0];

        item.rotated = rotated;
        item.fit = this.splitNode(node, rotated ? item.y : item.x, rotated ? item.x : item.y);
        return item.fit;
    }

    findNode(node, w, h) {
        if (node.used) {
            return this.findNode(node.right, w, h) || this.findNode(node.down, w, h);
        }

        if (w <= node.w && h <= node.h) {
            return node;
        }

        return null;
    }

    splitNode(node, w, h) {
        node.used = true;
        node.down = { x: node.x, y: node.y + h, w: node.w, h: node.h - h, used: false };
        node.right = { x: node.x + w, y: node.y, w: node.w - w, h: h, used: false };
        return node;
    }

    addFittedItem(item) {
        this.items.push(item);
    }

    getUsedPercentage() {
        const usedArea = this.items.reduce((acc, item) => acc + (item.x * item.y), 0);
        return (usedArea / this.totalArea) * 100;
    }
}

function binPacking(items, containerSize) {
    items.sort((a, b) => (b.x * b.y) - (a.x * a.y));

    const bins = [];

    for (const item of items) {
        let bestBinIndex = -1;

        for (let i = 0; i < bins.length; i++) {
            if (bins[i].insert(item)) {
                bestBinIndex = i;
                break;
            }
        }

        if (bestBinIndex === -1) {
            const newBin = new Guillotine(containerSize.x, containerSize.y);

            if (newBin.insert(item)) {
                newBin.addFittedItem(item);
                bins.push(newBin);
            } else {
                return null; /* throw???? */
            }
        } else {
            bins[bestBinIndex].addFittedItem(item);
        }
    }

    return bins;
}
const items = $state.context.LOCAL.dims.woProcesses.reduce((a,c)=>{
  const o = {
    "x":c.width.value,
    "y":c.length.value
  }
  return [...a, ...Array(c.quantity).fill(o)];
},[])
const containerSize = { "x": $state.context.LOCAL.dims.component.width.value, "y": $state.context.LOCAL.dims.component.length.value };
const bins = binPacking(items, containerSize);
const output = []
if (!bins) return null;
bins.forEach((bin, index) => {
  output.push(bin.getUsedPercentage())

});
const totalUsage = output.reduce((a,c)=>a+c,0)/(output.length);
const totalUsageWeight = totalUsage/100 * $state.context.LOCAL.dims.component.weight.value*output.length;
const totalWeight =  $state.context.LOCAL.dims.component.weight.value*output.length;
const woSum = $state.context.LOCAL.dims.woProcesses.reduce((a,c)=>a+(c.weight.value*c.quantity),0);
const scrapSum = $state.context.LOCAL.dims.component.weight.value*output.length-woSum
const usageRatio = $state.context.LOCAL.dims.woProcesses.map(v=>{
    const ratio = (v.weight.value*v.quantity)/woSum 
    return {
        "usagePercent":ratio*100,
        "workOrderProcessId":v.workOrderProcessId,
        "usagePercentPerUnit": (ratio*100)/v.quantity,
        "usageWeightPerUnit": (ratio*totalWeight)/v.quantity


    }
})
return {
    "componentUsagePercent":output,
    "componentUsageQuantity":output.length,
    "componentProductStrategyProcessId": $state.context.LOCAL.dims.component.productStrategyProcessId,
    "totalOutputWeight": woSum,
    "totalUtilizationPercentByWeight":woSum/totalWeight *100,
    "usagePerProcess":usageRatio
}

